function loadDemo(){try{const data=JSON.parse(safeRead(key));return data&&Array.isArray(data.services)?data:demoSeed()}catch{return demoSeed()}}
const initialData=loadDemo();
const state={role:'viewer',view:'home',data:initialData,modal:null,edit:null,tableSearch:'',category:'Semua',flash:'',busy:false,viewerIds:JSON.parse(safeRead('homecare-viewer-ids')||'[]'),caregiverId:1,bookingStep:1,draft:{service_id:1,units:2,distance_km:7,scheduled_date:today(),scheduled_time:'09:00',urgent:false,addons:[],promo_code:'',name:'',phone:'',email:'',address:'',patient_note:''},selectedBooking:null,menuOpen:false};
const persist=()=>{if(!CONFIG.api)safeWrite(key,JSON.stringify(state.data));safeWrite('homecare-viewer-ids',JSON.stringify(state.viewerIds))};
const getService=(id)=>state.data.services.find(s=>Number(s.id)===Number(id));
const getCustomer=(id)=>state.data.customers.find(s=>Number(s.id)===Number(id));
const getCaregiver=(id)=>state.data.caregivers.find(s=>Number(s.id)===Number(id));
function bookingRich(b){return {...b,service:b.service || getService(b.service_id),customer:b.customer || getCustomer(b.customer_id),caregiver:b.caregiver || getCaregiver(b.caregiver_id)}}
function viewerBookings(){if(state.role==='admin')return state.data.bookings;if(state.role==='caregiver')return state.data.bookings.filter(b=>Number(b.caregiver_id)===Number(state.caregiverId));return state.data.bookings.filter(b=>state.viewerIds.includes(Number(b.id)))}
function nextId(resource){return Math.max(0,...state.data[resource].map(x=>Number(x.id)||0))+1}
async function api(path,method='GET',payload){const headers={'Accept':'application/json','Content-Type':'application/json'};let csrf=document.querySelector('meta[name="csrf-token"]');if(csrf)headers['X-CSRF-TOKEN']=csrf.content;let res=await fetch(path,{method,credentials:'same-origin',headers,body:payload?JSON.stringify(payload):undefined});const data=await res.json().catch(()=>({message:`Kesalahan server (${res.status})`}));if(!res.ok)throw new Error(data.message || Object.values(data.errors||{})[0]?.[0] || 'Tidak dapat terhubung ke server.');return data;}
async function reloadApi(){if(!CONFIG.api)return;const data=await api('/api/bootstrap');state.data=data;state.role=data.role||state.role;}
const notify=(message,kind='ok')=>{let old=byId('toast');if(old)old.remove();const toast=document.createElement('div');toast.id='toast';toast.className=`toast ${kind}`;toast.setAttribute('role','status');toast.innerHTML=`<span class="toast-mark">${kind==='ok'?'✓':'!'}</span><span>${el(message)}</span><button aria-label="Tutup pemberitahuan" type="button">×</button>`;toast.querySelector('button').onclick=()=>toast.remove();document.body.append(toast);setTimeout(()=>toast.remove(),4500)};
