const brand=()=>`<div class="brand"><img class="brand-logo" src="${CONFIG.assets}logo-unai.png" alt="Logo resmi Universitas Advent Indonesia" width="48" height="48"><span class="brand-copy">Home Care<small>UNAI · DEMO</small></span></div>`;
const navItems=[['home','Beranda'],['services','Layanan'],['caregivers','Tim Medis'],['orders','Pesanan Saya'],['reviews','Ulasan'],['join','Daftar Mitra']];
const adminNav=[['dashboard','Dashboard','grid'],['bookings','Pemesanan','clipboard'],['services','Kelola Layanan','heart'],['caregivers','Tim Medis','users'],['customers','Pelanggan','users'],['promotions','Promo & Diskon','wallet'],['service_areas','Area Layanan','pin'],['applications','Pendaftaran Mitra','briefcase'],['reviews','Ulasan','star'],['reports','Laporan','chart'],['settings','Pengaturan','settings']];
function linkView(view,label,classes='',extra=''){return `<button type="button" data-view="${view}" class="${classes}" ${extra}>${label}</button>`;}
function viewerHeader(){return `<div class="announcement"><span class="sparkle">✦</span> Layanan home care yang lebih dekat, lebih mudah, lebih personal <span class="pill-mini">DEMO MODE</span></div><header class="site-header"><div class="container header-inner">${linkView('home',brand(),'brand-button')}<nav class="desktop-nav" aria-label="Navigasi utama">${navItems.slice(0,5).map(([v,t])=>linkView(v,t,`nav-link ${state.view===v?'active':''}`)).join('')}</nav><div class="header-actions">${linkView('login',`${icon('lock',16)} Masuk`, 'ghost-link')}${linkView('booking',`Pesan layanan ${icon('arrow',17)}`,'btn btn-dark')}<button class="menu-toggle" data-menu="toggle" aria-label="Buka navigasi">${icon('menu',22)}</button></div></div>${state.menuOpen?`<div class="mobile-nav">${navItems.map(([v,t])=>linkView(v,t,'mobile-nav-item')).join('')}${linkView('login','Masuk demo','mobile-nav-item')}</div>`:''}</header>`}
function viewerFooter(){return `<footer class="site-footer"><div class="container footer-grid"><div>${brand()}<p>Perawatan yang terasa dekat. Platform demo pemesanan home care dengan layanan personal di rumah.</p><div class="footer-social"><img class="unai-seal" src="${CONFIG.assets}logo-unai.png" alt="Logo UNAI dari project asli" width="25" height="25" /> <span>© ${new Date().getFullYear()} Home Care UNAI · Prototype</span></div></div><div><h4>Jelajahi</h4>${[['services','Layanan'],['caregivers','Tenaga kesehatan'],['booking','Buat pemesanan'],['orders','Status pesanan']].map(([v,t])=>linkView(v,t,'footer-link')).join('')}</div><div><h4>Perusahaan</h4>${[['join','Jadi mitra'],['reviews','Cerita pelanggan'],['help','Pusat bantuan'],['login','Login demo']].map(([v,t])=>linkView(v,t,'footer-link')).join('')}</div><div><h4>Informasi demo</h4><p>${icon('pin',15)} Area contoh: Bandung, Cimahi, Lembang</p><p>${icon('clock',15)} Booking berdasarkan ketersediaan tim</p><p class="footer-note">Bukan situs layanan medis resmi dan tidak untuk kondisi darurat.</p></div></div><div class="container footer-bottom">Harga, petugas, ulasan, dan data pelanggan hanya simulasi. Belum menerima pembayaran.</div></footer>`}
function adminShell(content){const current=adminNav.find(([v])=>v===state.view);return `<div class="admin-layout"><aside class="admin-sidebar"><div class="admin-logo">${brand()}</div><div class="sidebar-overline">MENU UTAMA</div><nav>${adminNav.map(([v,label,ico])=>linkView(v,`${icon(ico,19)} <span>${el(label)}</span>`, `side-link ${v===state.view?'selected':''}`)).join('')}</nav><div class="sidebar-bottom"><div class="demo-identity"><span class="demo-avatar">AD</span><span><strong>Admin Demo</strong><small>Administrator</small></span>${icon('chevron',16)}</div>${linkView('home',`${icon('logout',17)} Lihat sebagai pelanggan`,'side-link switch-link','data-role="viewer"')}</div></aside><div class="admin-stage"><div class="admin-topbar"><div class="admin-breadcrumb">Workspace <span>/</span> <strong>${el(current?.[1]||'Dashboard')}</strong></div><div class="admin-top-actions"><span class="live-dot"></span><span class="admin-demo-chip">Demo workspace</span>${linkView('home','Tampilan pelanggan','topbar-link','data-role="viewer"')}<div class="top-avatar">AD</div></div></div><main class="admin-main">${content}</main></div></div>`}
function caregiverShell(content){const caregiver=getCaregiver(state.caregiverId)||state.data.caregivers[0];return `<div class="admin-layout caregiver-layout"><aside class="admin-sidebar"><div class="admin-logo">${brand()}</div><div class="sidebar-overline">RUANG PETUGAS</div><nav>${linkView('caregiver-dashboard',`${icon('grid',19)} <span>Dashboard</span>`,'side-link selected')}${linkView('caregiver-schedule',`${icon('calendar',19)} <span>Jadwal saya</span>`,'side-link')}</nav><div class="sidebar-bottom"><div class="demo-identity"><span class="demo-avatar">${el(caregiver?.initials||'PT')}</span><span><strong>${el(caregiver?.name||'Petugas Demo')}</strong><small>Profil contoh</small></span></div>${linkView('home',`${icon('logout',17)} Lihat sebagai pelanggan`,'side-link switch-link','data-role="viewer"')}</div></aside><div class="admin-stage"><div class="admin-topbar"><div class="admin-breadcrumb">Ruang petugas <span>/</span> <strong>Jadwal saya</strong></div><div class="admin-top-actions"><span class="admin-demo-chip">Data simulasi</span>${linkView('home','Tampilan pelanggan','topbar-link','data-role="viewer"')}<div class="top-avatar">${el(caregiver?.initials||'PT')}</div></div></div><main class="admin-main">${content}</main></div></div>`}
function heading(eyebrow,title,desc){return `<div class="section-heading"><div><div class="eyebrow">${el(eyebrow)}</div><h2>${title}</h2><p>${el(desc)}</p></div></div>`}
function cardService(s,index=0){const image=photos.services[index%photos.services.length];return `<article class="service-card"><div class="service-art"><img src="${image}" alt="Suasana layanan ${el(s.name)}" loading="lazy"><span class="service-count">0${index+1}</span><span class="service-photo-icon">${icon(s.icon,20)}</span></div><div class="service-card-body"><div class="service-category">${el(s.category)}</div><h3>${el(s.name)}</h3><p>${el(s.description)}</p><div class="service-card-foot"><div><small>Mulai dari</small><strong>${rupee(s.price)} <em>/ ${unitLabel(s.unit)}</em></strong></div>${linkView('booking',icon('arrow',19),'round-arrow',`data-service="${s.id}" aria-label="Pesan ${el(s.name)}"`)}</div></div></article>`}
function teamCard(c){const image=photos.caregivers[(Number(c.id||1)-1)%photos.caregivers.length];return `<article class="team-card"><div class="team-avatar"><img src="${image}" alt="Foto ilustratif profil ${el(c.name)}" loading="lazy"><span class="available-badge">${c.available?'● Tersedia':'○ Tidak tersedia'}</span></div><div class="team-body"><span class="sample-tag">PROFIL FIKTIF DEMO</span><span class="team-role">${el(c.role)}</span><h3>${el(c.name)}</h3><p>${el(c.speciality)}</p><div class="team-stats"><span>${icon('star',15)} ${Number(c.rating).toFixed(1)}</span><span>${icon('briefcase',15)} ${Number(c.experience_years)} tahun</span><span>${icon('pin',15)} ${el(c.city)}</span></div></div></article>`}
function homePage(){const services=state.data.services.filter(s=>s.active);return `<main><section class="hero-section"><div class="container hero-grid"><div class="hero-copy"><div class="hero-tag"><span class="tag-icon">${icon('checkcircle',15)}</span> Kesehatan keluarga, prioritas kami</div><h1>Perawatan terbaik, <span>langsung ke rumah.</span></h1><p>Pesan perawat, fisioterapis, dan layanan pendampingan dengan mudah. Lebih tenang untuk keluarga, lebih nyaman untuk Anda.</p><div class="hero-ctas">${linkView('booking',`Pesan sekarang ${icon('arrow',18)}`,'btn btn-primary btn-lg')}${linkView('services',`${icon('grid',18)} Jelajahi layanan`,'btn btn-soft btn-lg')}</div><div class="hero-trust"><img src="${CONFIG.assets}logo-unai.png" alt="UNAI" width="44" height="44"><div><strong>Didukung identitas UNAI</strong><small>Prototype layanan home care yang humanis</small></div></div></div><div class="hero-visual"><figure class="hero-photo"><img src="${photos.hero}" alt="Perawat mendampingi pasien lansia dengan hangat"><figcaption>Foto ilustratif layanan home care</figcaption></figure><div class="float-card float-top">${icon('shield',18)} <span><strong>Pendampingan personal</strong><small>Berpusat pada kebutuhan keluarga</small></span></div><div class="float-card float-bottom"><span class="mini-check">${icon('check',17)}</span><span><strong>Pemesanan mudah</strong><small>Jadwalkan sesuai kebutuhan</small></span></div></div></div></section><div class="container benefit-bar"><div>${icon('shield',25)}<span><strong>Pelayanan terpercaya</strong><small>Tim kesehatan berpengalaman</small></span></div><div>${icon('clock',25)}<span><strong>Jadwal fleksibel</strong><small>Pilih waktu sesuai kebutuhan</small></span></div><div>${icon('wallet',25)}<span><strong>Biaya transparan</strong><small>Lihat rincian sebelum pesan</small></span></div></div><section class="section-spacious section-white"><div class="container">${heading('LAYANAN KAMI','Yang terbaik untuk kebutuhan keluarga','Pilih layanan home care yang sesuai. Setiap harga bisa dihitung secara transparan sebelum pemesanan.')}<div class="services-grid">${services.slice(0,6).map((s,i)=>cardService(s,i)).join('')}</div><div class="center-actions">${linkView('services',`Lihat semua layanan ${icon('arrow',17)}`,'btn btn-outline')}</div></div></section><section class="section-spacious process-section"><div class="container process-layout"><figure class="process-photo"><img src="${photos.consultation}" alt="Dokter berkonsultasi dengan pasien lansia" loading="lazy"></figure><div>${heading('BAGAIMANA CARANYA','Mudah, hanya tiga langkah','Dari pemilihan layanan hingga petugas datang ke rumah Anda.')}<div class="steps-grid">${[['01','Pilih layanan','Jelajahi daftar perawatan sesuai kondisi dan kebutuhan keluarga.','heart'],['02','Atur jadwal & biaya','Isi waktu kunjungan, durasi, jarak, dan lihat simulasi total harga.','calendar'],['03','Pantau pesanan','Simpan pesanan, lihat status, lalu unduh rincian struk.','receipt']].map(([n,t,d,i])=>`<div class="step-card"><span class="step-no">${n}</span><div class="step-icon">${icon(i,25)}</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div></div></section><section class="section-spacious section-white"><div class="container"><div class="flex-title">${heading('TIM HOME CARE','Didukung tenaga pilihan','Petugas contoh untuk memvisualisasikan pengalaman layanan pelanggan.')} ${linkView('caregivers',`Lihat seluruh tim ${icon('arrow',16)}`,'text-link')}</div><div class="team-grid">${state.data.caregivers.filter(c=>c.available).slice(0,3).map(teamCard).join('')}</div></div></section><section class="container home-cta"><div><div class="eyebrow">CARE STARTS HERE</div><h2>Perawatan yang Anda butuhkan, <span>di mana pun Anda berada.</span></h2><p>Simulasikan tarif layanan, pilih jadwal kunjungan, dan lanjutkan ke pemesanan demo.</p>${linkView('booking',`Mulai pemesanan ${icon('arrow',19)}`,'btn btn-light btn-lg')}</div><img class="cta-photo" src="${photos.care}" alt="Konsultasi kesehatan yang penuh perhatian" loading="lazy"></section></main>`}
function servicesPage(){const cats=['Semua',...new Set(state.data.services.filter(s=>s.active).map(s=>s.category))];const items=state.data.services.filter(s=>s.active&&(state.category==='Semua'||s.category===state.category));return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">SOLUSI PERAWATAN DI RUMAH</div><h1>Layanan kami, untuk <span>setiap kebutuhan.</span></h1><p>Rincian harga awal dan durasi yang bisa disesuaikan. Pilih untuk mulai menyusun pesanan Anda.</p></div></div><section class="container listing-wrap"><div class="category-tabs">${cats.map(cat=>`<button type="button" data-category="${el(cat)}" class="category-tab ${state.category===cat?'selected':''}">${el(cat)}</button>`).join('')}</div><div class="services-grid">${items.map((s,i)=>cardService(s,i)).join('')}</div>${!items.length?emptyState('Belum ada layanan aktif dalam kategori ini.'):''}<div class="notice-inline">${icon('info',18)} Harga yang terlihat adalah tarif dasar. Biaya perjalanan, waktu, add-on, dan diskon diperhitungkan dalam simulasi saat pemesanan.</div></section></main>`}
function caregiversPage(){return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">PEOPLE BEHIND THE CARE</div><h1>Kenalan dengan <span>tim kami.</span></h1><p>Kenali tenaga kesehatan yang siap mendampingi kebutuhan perawatan di rumah.</p></div></div><section class="container listing-wrap"><div class="team-grid">${state.data.caregivers.filter(c=>c.available).map(teamCard).join('')}</div><div class="notice-inline">${icon('info',18)} Data petugas, pengalaman, dan rating merupakan contoh untuk demo, bukan profil tenaga medis terverifikasi.</div></section></main>`}
function viewerHeaderV2(){return viewerHeader().replace('<span class="sparkle">✦</span> Layanan home care yang lebih dekat, lebih mudah, lebih personal','<strong>DEMO INTERAKTIF</strong> · Seluruh layanan, profil, dan aktivitas menggunakan data simulasi')}
function homePageV2(){let html=homePage();html=html.replace('Tenaga profesional</strong><small>Perawatan lebih personal di rumah','Profil petugas contoh</strong><small>Identitas dan kredensial hanya simulasi').replace('Pelayanan terpercaya</strong><small>Tim kesehatan berpengalaman','Alur layanan terstruktur</strong><small>Dari pemesanan sampai struk').replace('Jadwal fleksibel</strong><small>Pilih waktu sesuai kebutuhan','Jadwal dapat dipilih</strong><small>Gunakan tanggal dan waktu demo').replace('Mudah, hanya tiga langkah','Alur layanan yang dapat ditinjau').replace('BAGAIMANA CARANYA','ALUR PEMESANAN DEMO').replace('CARE STARTS HERE','MULAI SIMULASI').replace('<div class="steps-grid">','<div class="steps-grid"><div class="step-card"><span class="step-no">00</span><div class="step-icon">'+icon('info',25)+'</div><h3>Kenali batas layanan</h3><p>Baca cakupan demo dan gunakan layanan darurat resmi untuk kondisi gawat.</p></div>');return html;}
function caregiversPageV2(){return caregiversPage().replace('PEOPLE BEHIND THE CARE','PROFIL PETUGAS CONTOH').replace('Kenali tenaga kesehatan yang siap mendampingi kebutuhan perawatan di rumah.','Pelajari tampilan direktori petugas menggunakan identitas, pengalaman, dan rating fiktif.')}
function reviewsPageV2(){return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">ULASAN PELANGGAN</div><h1>Pengalaman nyata, <span>setelah layanan berjalan.</span></h1><p>Demo ini tidak menampilkan testimonial fiktif. Ulasan yang dikirim masuk ke antrean moderasi.</p></div></div><div class="container listing-wrap review-layout"><div>${emptyState('Belum ada ulasan pelanggan terverifikasi.')}</div><form id="review-form" class="panel side-form"><div class="eyebrow">KIRIM ULASAN DEMO</div><h3>Uji alur moderasi</h3><p>Isian disimpan sebagai data demo dan tidak dipublikasikan sebagai testimonial nyata.</p><label class="field">Nama<input name="name" required minlength="2" placeholder="Nama Anda"></label><label class="field">Layanan<select name="service_id"><option value="">Pilih layanan (opsional)</option>${state.data.services.map(s=>`<option value="${s.id}">${el(s.name)}</option>`).join('')}</select></label><label class="field">Rating<select name="rating"><option value="5">★★★★★ · 5</option><option value="4">★★★★ · 4</option><option value="3">★★★ · 3</option><option value="2">★★ · 2</option><option value="1">★ · 1</option></select></label><label class="field">Ulasan<textarea name="comment" required minlength="10" rows="4" placeholder="Tuliskan masukan untuk simulasi moderasi"></textarea></label><button class="btn btn-primary btn-block" type="submit">Kirim ke moderasi ${icon('arrow',16)}</button></form></div></main>`}
function emptyState(msg,cta=false){return `<div class="empty-state"><div class="empty-icon">${icon('clipboard',28)}</div><h3>Belum ada data</h3><p>${el(msg)}</p>${cta?linkView('booking',`Buat pemesanan ${icon('arrow',16)}`,'btn btn-primary'):''}</div>`}
function serviceSelect(selected){return state.data.services.filter(s=>s.active).map(s=>`<option value="${s.id}" ${Number(selected)===Number(s.id)?'selected':''}>${el(s.name)} · ${rupee(s.price)}/${unitLabel(s.unit)}</option>`).join('')}
function quoteDraft(){try{return {value:calculateQuote(getService(state.draft.service_id),state.draft,state.data.promotions)}}catch(e){return {error:e.message}}}
function receiptRows(quote){return breakdownRows(quote).filter(([name,amount])=>amount || /Layanan|platform/i.test(name)).map(([name,amount])=>`<div class="cost-row"><span>${el(name)}</span><strong class="${amount<0?'discount':''}">${amount<0?'-':''}${rupee(Math.abs(amount))}</strong></div>`).join('')}
function quotePanel(){const {value:q,error}=quoteDraft();return `<div class="quote-panel"><div class="quote-title"><span>${icon('receipt',19)} Rincian biaya</span><span class="quote-live"><i></i> Estimasi langsung</span></div>${error?`<div class="form-alert">${el(error)}</div>`:`<div class="quote-service"><span class="small-muted">Layanan dipilih</span><strong>${el(q.service_name)}</strong></div><div class="cost-lines">${receiptRows(q)}</div><div class="quote-total"><span>Estimasi total</span><strong>${rupee(q.total)}</strong></div><p class="pricing-disclaimer">${icon('info',14)} Harga simulasi, belum ditagihkan. Jarak diisi manual dan jadwal masih perlu konfirmasi.</p><button type="submit" form="booking-form" class="btn btn-primary btn-block btn-lg">Konfirmasi pesanan ${icon('arrow',18)}</button>`}</div>`}
function bookingPage(){const d=state.draft;const active=state.data.services.filter(s=>s.active);if(!active.length)return `<main class="page-main container">${emptyState('Tidak ada layanan aktif saat ini.')}</main>`;if(!getService(d.service_id)||!getService(d.service_id).active){d.service_id=active[0].id;d.units=active[0].min_units}return `<main class="booking-background"><div class="container"><div class="booking-head"><div><span class="eyebrow">PESAN LAYANAN</span><h1>Mulai perawatan dari sini.</h1><p>Atur jadwal, pilih kebutuhan, dan lihat detail biaya secara transparan sebelum konfirmasi.</p></div><div class="breadcrumb-steps"><span class="active">01 <b>Detail pesanan</b></span>${icon('chevron',17)}<span>02 <b>Konfirmasi</b></span>${icon('chevron',17)}<span>03 <b>Struk</b></span></div></div><div class="booking-layout"><form id="booking-form" class="booking-form panel" novalidate><div class="form-block"><div class="form-block-head"><span class="block-step">01</span><div><h3>Pilih layanan</h3><p>Sesuaikan dengan kebutuhan perawatan</p></div></div><div class="form-fields"><label class="field full">Jenis layanan<select name="service_id" required>${serviceSelect(d.service_id)}</select></label><label class="field">Durasi / jumlah <span class="field-hint">Min. ${getService(d.service_id)?.min_units || 1} ${unitLabel(getService(d.service_id)?.unit)}</span><input type="number" name="units" min="${getService(d.service_id)?.min_units||1}" max="30" step="1" required value="${el(d.units)}"></label><label class="field">Perkiraan jarak dari titik layanan (km)<input type="number" name="distance_km" min="0" max="200" step="0.5" required value="${el(d.distance_km)}"><small>5 km pertama gratis, selebihnya ${rupee(POLICY.extraKm)}/km (dibulatkan ke atas)</small></label></div></div><div class="form-block"><div class="form-block-head"><span class="block-step">02</span><div><h3>Jadwal kunjungan</h3><p>Pilih hari dan jam sesuai kebutuhan</p></div></div><div class="form-fields"><label class="field">Tanggal kunjungan<input type="date" name="scheduled_date" required min="${today()}" value="${el(d.scheduled_date)}"></label><label class="field">Waktu kunjungan<input type="time" name="scheduled_time" required value="${el(d.scheduled_time)}"></label><label class="check-row full"><input type="checkbox" name="urgent" ${d.urgent?'checked':''}><span><strong>Layanan prioritas / mendesak</strong><small>Tambahan ${rupee(POLICY.urgent)}. Bukan layanan gawat darurat.</small></span></label></div></div><div class="form-block"><div class="form-block-head"><span class="block-step">03</span><div><h3>Tambahan layanan</h3><p>Opsional untuk kenyamanan keluarga</p></div></div><div class="addon-options">${Object.entries(ADDONS).map(([code,a])=>`<label class="addon-row"><input type="checkbox" name="addon_${code}" ${d.addons.includes(code)?'checked':''}><span>${icon(code==='report'?'file':code==='companion'?'users':'shield',21)}<span><strong>${el(a.name)}</strong><small>Tambahan layanan</small></span></span><b>+${rupee(a.price)}</b></label>`).join('')}</div><label class="field full promo-field">Kode promo (opsional)<div class="input-suffix"><input name="promo_code" placeholder="Contoh: CARE10" value="${el(d.promo_code)}"><span>${icon('wallet',18)}</span></div><small>Coba kode <button type="button" class="text-inline" data-promo="CARE10">CARE10</button> untuk simulasi diskon 10%.</small></label></div><div class="form-block last"><div class="form-block-head"><span class="block-step">04</span><div><h3>Informasi pemesan</h3><p>Data digunakan untuk kebutuhan kunjungan</p></div></div><div class="form-fields"><label class="field">Nama lengkap<input name="name" minlength="2" maxlength="120" required placeholder="Nama pemesan" value="${el(d.name)}"></label><label class="field">Nomor WhatsApp<input name="phone" required inputmode="tel" pattern="[+0-9 -]{9,20}" placeholder="08xxxxxxxxxx" value="${el(d.phone)}"></label><label class="field full">Alamat email (opsional)<input type="email" name="email" placeholder="nama@email.com" value="${el(d.email)}"></label><label class="field full">Alamat lengkap kunjungan<textarea name="address" rows="3" minlength="8" maxlength="500" required placeholder="Jalan, nomor rumah, kecamatan, kota, patokan lokasi">${el(d.address)}</textarea></label><label class="field full">Catatan kondisi / kebutuhan (opsional)<textarea name="patient_note" rows="3" maxlength="1000" placeholder="Tulis informasi yang perlu diketahui tim">${el(d.patient_note)}</textarea></label></div><p class="form-legal">${icon('shield',15)} Data yang Anda isi hanya digunakan untuk simulasi demo. Jangan masukkan informasi medis pribadi yang sesungguhnya.</p></div></form><aside class="booking-summary"><div id="quote-panel">${quotePanel()}</div><div class="security-notice">${icon('shield',20)}<span><strong>Pemesanan transparan</strong><small>Rincian harga tampil sebelum konfirmasi. Setelah pesan, struk dapat dilihat dan diunduh.</small></span></div></aside></div></div></main>`}
function bookingWizardPage(){
 const step=Math.min(5,Math.max(1,Number(state.bookingStep)||1));
 const labels=['Layanan','Jadwal','Lokasi & tambahan','Data pemesan','Konfirmasi'];
 const d=state.draft;
 const q=quoteDraft().value;
 let html=bookingPage();
 html=html.replace('<main class="booking-background">',`<main class="booking-background booking-step-${step}">`);
 html=html.replace(/<div class="breadcrumb-steps">[\s\S]*?<\/div><\/div><div class="booking-layout">/,`<div class="wizard-progress" aria-label="Progres pemesanan"><strong>Langkah ${step} dari 5</strong><div>${labels.map((label,index)=>`<span class="${index+1===step?'active':''} ${index+1<step?'done':''}"><i>${index+1}</i><b>${label}</b></span>`).join('')}</div></div></div><div class="booking-layout">`);
 const review=`<section class="booking-review-panel"><div class="form-block-head"><span class="block-step">05</span><div><h3>Tinjau dan konfirmasi</h3><p>Pastikan jadwal, alamat, dan estimasi biaya sudah benar.</p></div></div><dl class="review-summary"><div><dt>Layanan</dt><dd>${el(getService(d.service_id)?.name||'Layanan')}</dd></div><div><dt>Jadwal</dt><dd>${dateID(d.scheduled_date)} · ${el(d.scheduled_time)} WIB</dd></div><div><dt>Pemesan</dt><dd>${el(d.name||'Belum diisi')}</dd></div><div><dt>Alamat</dt><dd>${el(d.address||'Belum diisi')}</dd></div><div><dt>Total estimasi</dt><dd>${q?rupee(q.total):'Periksa data harga'}</dd></div></dl><p class="form-legal">${icon('info',15)} Ini adalah pemesanan demo dan bukan permintaan layanan medis nyata.</p></section>`;
 const nav=`<div class="wizard-actions">${step>1?'<button type="button" class="btn btn-outline" data-booking-back>Langkah sebelumnya</button>':'<span></span>'}${step<5?'<button type="button" class="btn btn-primary" data-booking-next>Lanjutkan</button>':''}</div>`;
 return html.replace('</form><aside class="booking-summary">',`${review}${nav}</form><aside class="booking-summary">`);
}
function validateBookingStep(step){const d=state.draft;if(step===1){const service=getService(d.service_id);if(!service||Number(d.units)<Number(service.min_units)||Number(d.distance_km)<0)throw new Error('Lengkapi pilihan layanan, durasi, dan jarak.');}if(step===2){if(!d.scheduled_date||!d.scheduled_time)throw new Error('Pilih tanggal dan waktu kunjungan.');}if(step===4){validateBooking({...d,email:d.email||'',patient_note:d.patient_note||''});}}
function moveBookingStep(direction){try{if(direction>0)validateBookingStep(state.bookingStep);state.bookingStep=Math.min(5,Math.max(1,state.bookingStep+direction));render();}catch(error){notify(error.message,'error')}}
function ordersPage(){const rows=viewerBookings().map(bookingRich).sort((a,b)=>Number(b.id)-Number(a.id));return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">MY APPOINTMENTS</div><h1>Riwayat <span>pesanan saya.</span></h1><p>Pantau status pemesanan dan akses kembali rincian biaya melalui struk digital.</p></div></div><section class="container listing-wrap">${rows.length?`<div class="orders-list">${rows.map(b=>`<article class="order-card"><div class="order-icon">${icon(b.service?.icon||'heart',26)}</div><div class="order-details"><span class="order-code">${el(b.code)}</span><h3>${el(b.service?.name||'Layanan')}</h3><p>${icon('calendar',15)} ${dateID(b.scheduled_date)} · ${el(b.scheduled_time?.slice(0,5))} WIB <span class="sep">•</span>${icon('pin',15)} ${el(b.distance_km)} km</p></div><div class="order-meta">${statBadge(b.status)}<strong>${rupee(b.total)}</strong></div><div class="order-actions"><button class="btn btn-outline btn-sm" data-receipt="${b.id}">${icon('receipt',16)} Lihat struk</button></div></article>`).join('')}</div>`:emptyState('Belum ada pesanan dari sesi demo Anda. Buat pemesanan untuk melihat struk digital.',true)}</section></main>`}
function reviewsPage(){return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">CERITA PELANGGAN</div><h1>Pengalaman perawatan, <span>lebih dekat.</span></h1><p>Baca ulasan contoh dan kirim tanggapan untuk simulasi moderasi admin.</p></div></div><div class="container listing-wrap review-layout"><div><div class="review-list">${state.data.reviews.filter(r=>r.published).map(r=>`<article class="review-card"><div class="stars">${'★'.repeat(Math.min(5,r.rating))}${'☆'.repeat(5-Math.min(5,r.rating))}</div><p>“${el(r.comment)}”</p><div class="review-by"><span class="tiny-avatar">${el(r.name[0])}</span><div><strong>${el(r.name)}</strong><small>Pengalaman layanan ${el(getService(r.service_id)?.name||'Home Care')}</small></div></div></article>`).join('')}</div></div><form id="review-form" class="panel side-form"><div class="eyebrow">BERI ULASAN</div><h3>Bagikan pengalaman Anda</h3><p>Ulasan baru akan ditinjau admin sebelum tampil.</p><label class="field">Nama<input name="name" required minlength="2" placeholder="Nama Anda"></label><label class="field">Layanan<select name="service_id"><option value="">Pilih layanan (opsional)</option>${state.data.services.map(s=>`<option value="${s.id}">${el(s.name)}</option>`).join('')}</select></label><label class="field">Rating<select name="rating"><option value="5">★★★★★ — 5</option><option value="4">★★★★ — 4</option><option value="3">★★★ — 3</option><option value="2">★★ — 2</option><option value="1">★ — 1</option></select></label><label class="field">Ulasan<textarea name="comment" required minlength="10" rows="4" placeholder="Bagaimana pengalaman layanan Anda?"></textarea></label><button class="btn btn-primary btn-block" type="submit">Kirim ulasan ${icon('arrow',16)}</button></form></div></main>`}
function joinPage(){return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">GROW WITH US</div><h1>Jadi bagian dari <span>tim peduli.</span></h1><p>Daftarkan diri Anda sebagai mitra Home Care UNAI lewat formulir demo.</p></div></div><section class="container listing-wrap narrow"><form class="panel join-form" id="join-form"><h2>Formulir pendaftaran mitra</h2><p>Isi informasi berikut. Tim admin demo dapat meninjau pendaftaran Anda.</p><div class="form-fields"><label class="field">Nama lengkap<input name="name" required minlength="2" placeholder="Nama sesuai identitas"></label><label class="field">Email<input type="email" name="email" required placeholder="nama@email.com"></label><label class="field">Nomor WhatsApp<input name="phone" required placeholder="08xxxxxxxxxx"></label><label class="field">Profesi<select name="profession" required><option>Perawat</option><option>Fisioterapis</option><option>Caregiver</option><option>Tenaga kesehatan lainnya</option></select></label><label class="field">Pengalaman (tahun)<input type="number" name="experience_years" required min="0" max="60" value="1"></label><label class="field full">Motivasi bergabung<textarea name="motivation" rows="5" placeholder="Cerita singkat tentang pengalaman dan motivasi Anda"></textarea></label></div><button class="btn btn-primary" type="submit">Kirim pendaftaran ${icon('arrow',17)}</button><p class="pricing-disclaimer">Simulasi pendaftaran; bukan rekrutmen resmi.</p></form></section></main>`}
function helpPage(){return `<main class="page-main"><div class="page-hero"><div class="container"><div class="eyebrow">PUSAT BANTUAN</div><h1>Pertanyaan <span>yang sering muncul.</span></h1><p>Informasi penting tentang alur pemesanan dan tarif dalam versi demo.</p></div></div><div class="container listing-wrap faq-list">${[['Bagaimana cara memesan layanan?','Klik Pesan layanan, tentukan jenis layanan, tanggal, durasi, jarak, dan isi data pemesan. Setelah klik konfirmasi, Anda mendapat nomor pesanan serta struk.'],['Bagaimana biaya kunjungan dihitung?','Total = tarif dasar × durasi, ditambah biaya jarak lewat 5 km, biaya waktu malam atau akhir pekan, prioritas, add-on, biaya platform, dikurangi promo.'],['Bisakah struk diunduh?','Ya. Buka Pesanan Saya, klik Lihat struk, lalu Download PDF atau Cetak struk. Struk demo bukan bukti pembayaran.'],['Apakah pembayaran sudah aktif?','Belum. Semua data, status, promosi dan tarif pada demo hanya simulasi. Tidak ada payment gateway.'],['Apakah login membutuhkan akun?','Tidak untuk demo. Halaman login tetap ada, tetapi Anda bisa langsung masuk sebagai pelanggan atau admin. Akses ini tidak boleh digunakan untuk produksi.'],['Apakah layanan untuk kondisi darurat?','Tidak. Untuk keadaan gawat darurat segera hubungi layanan darurat atau fasilitas kesehatan resmi.']].map(([q,a])=>`<details><summary>${el(q)} ${icon('ChevronDown',18)}</summary><p>${el(a)}</p></details>`).join('')}</div></main>`}
function loginPage(){return `<main class="login-page"><div class="login-visual" style="--login-photo:url('${photos.hero}')"><div class="login-visual-inner"><img class="login-seal" src="${CONFIG.assets}logo-unai.png" alt="Logo resmi UNAI"><div class="eyebrow light">AKSES DEMO</div><h2>Tiga peran, satu alur layanan.</h2><p>Tinjau perjalanan pelanggan, operasi admin, dan jadwal petugas menggunakan data simulasi.</p><small>Seluruh identitas dan aktivitas di layar ini adalah contoh.</small></div></div><div class="login-panel"><div class="login-form-wrap">${linkView('home',icon('arrowleft',18)+' Kembali ke beranda','back-link')}<div class="login-mobile-brand">${brand()}</div><span class="eyebrow">PILIH PERAN DEMO</span><h1>Masuk tanpa kredensial<span>.</span></h1><p>Mode demo tidak memeriksa email atau kata sandi. Jangan gunakan akses ini untuk data atau operasional nyata.</p><button class="btn btn-primary btn-block btn-lg" data-role="viewer" data-view="home">Masuk sebagai pelanggan</button><button class="btn btn-outline btn-block" data-role="admin" data-view="dashboard">${icon('grid',18)} Masuk sebagai admin</button><button class="btn btn-outline btn-block" data-role="caregiver" data-view="caregiver-dashboard">${icon('briefcase',18)} Masuk sebagai petugas</button><p class="login-bottom">Anda dapat kembali ke tampilan pelanggan dari setiap dashboard.</p></div></div></main>`}
const resourceMeta={
 services:{title:'Kelola layanan',desc:'Atur katalog, tarif, durasi, kategori, dan ketersediaan layanan.',singular:'Layanan',icon:'heart',cols:[['name','Nama layanan'],['category','Kategori'],['price','Tarif'],['unit','Satuan'],['active','Status']]},
 caregivers:{title:'Tim medis & caregiver',desc:'Pantau tenaga kesehatan, spesialisasi, dan status ketersediaan.',singular:'Petugas',icon:'users',cols:[['name','Nama petugas'],['role','Profesi'],['speciality','Keahlian'],['rating','Rating'],['available','Ketersediaan']]},
 customers:{title:'Data pelanggan',desc:'Kelola data pemesan yang tersimpan dalam sistem.',singular:'Pelanggan',icon:'users',cols:[['name','Nama'],['phone','WhatsApp'],['email','Email'],['address','Alamat']]},
 promotions:{title:'Promo & diskon',desc:'Kelola kode promo, nilai potongan, batas diskon, dan tanggal berakhir.',singular:'Promo',icon:'wallet',cols:[['code','Kode promo'],['type','Jenis'],['value','Nilai'],['max_discount','Maks. diskon'],['active','Status']]},
 service_areas:{title:'Area layanan',desc:'Atur wilayah cakupan sebagai informasi untuk pelanggan.',singular:'Area',icon:'pin',cols:[['name','Nama area'],['city','Kota'],['coverage_km','Cakupan (km)'],['active','Status']]},
 applications:{title:'Pendaftaran mitra',desc:'Tinjau pendaftaran tenaga kesehatan dan perbarui tahap seleksi.',singular:'Pendaftar',icon:'briefcase',cols:[['name','Nama'],['profession','Profesi'],['email','Email'],['experience_years','Pengalaman'],['status','Status']]},
 reviews:{title:'Ulasan pelanggan',desc:'Moderasi komentar untuk ditampilkan di situs pelanggan.',singular:'Ulasan',icon:'star',cols:[['name','Nama'],['rating','Rating'],['comment','Komentar'],['published','Publik']]},
};
