(async()=>{if(CONFIG.api){try{await reloadApi()}catch(e){byId('app').innerHTML=`<main class="load-error"><h1>Gagal menyiapkan backend</h1><p>${el(e.message)}</p><p>Jalankan migration dan seeder Laravel, atau buka <strong>preview/index.html</strong> untuk demo offline.</p></main>`;return}}render()})();
